package com.dudleylane.quickfix.fix42;

/** FIX 4.2 Logout (35=5). Generated by spec/GeneratorJava.rb. */
public class Logout extends Message {
    public static final String MSGTYPE = "5";

    public Logout() {
        getHeader().setField(35, MSGTYPE);
    }

    private Logout(long cPtr) {
        super(cPtr, false);
    }

    /**
     * message as a Logout, without copying it: the same engine object, so valid only while message is. A
     * callback's message is the engine's and lasts only for the callback; copy it (new Message(message)) to keep it.
     */
    public static Logout view(com.dudleylane.quickfix.Message message) {
        if (!MSGTYPE.equals(message.getHeader().getField(35))) {
            throw new IllegalArgumentException("not a Logout (35=" + MSGTYPE + "): 35=" + message.getHeader().getField(35));
        }
        return new Logout(getCPtr(message));
    }
}
